/**
 * Embed the omp preset's Markdown rules into `src/omp-preset.gen.ts`.
 *
 * The daemon is a `bun build --compile` single file, so the preset cannot be read from the
 * package directory at runtime; the sources stay in `presets/omp/` (copied unchanged from
 * akhook) and this script is the only thing that turns them into code. `test/preset.test.ts`
 * fails when the generated file is stale.
 */
import { readdirSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const root = join(import.meta.dirname, "..");
const dir = join(root, "presets", "omp");
const names = readdirSync(dir)
  .filter((file) => file.endsWith(".md") && file !== "README.md")
  .map((file) => file.slice(0, -3))
  .sort();

const lines = [
  "/* eslint-disable */",
  "// Generated by scripts/embed-presets.ts from presets/omp/*.md. Do not edit.",
  "export const OMP_PRESET: Readonly<Record<string, string>> = {",
  ...names.map(
    (name) =>
      `  ${JSON.stringify(name)}: ${JSON.stringify(readFileSync(join(dir, `${name}.md`), "utf8"))},`,
  ),
  "};",
  "",
];
writeFileSync(join(root, "src", "omp-preset.gen.ts"), lines.join("\n"));
console.log(`embedded ${names.length} rules`);
